mapper.select:
select tcs.id, tcs.pilot_id, tcs.assistant_id, tcs.flight_id, tcp.name as pilot_name, tca.name as assistant_name, tcs.status, tcs.duty_type, tcs.create_time, tcs.update_time from tb_crew_schedule tcs left join tb_crew tcp on tcs.pilot_id = tcp.id and tcp.is_deleted = 0 left join tb_crew tca on tcs.assistant_id = tca.id and tca.is_deleted = 0
and tcs.is_deleted = 0
and tcs.flight_id = #{flightId}
and tcs.pilot_id = #{pilotId}
and tcs.assistant_id = #{assistantId}
and tcs.status = #{status}
and tcs.duty_type = #{dutyType}
